import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class ServiceProviderGraphAlgebraCompatibilityTest {

	private static final String ENDPOINT = "urn:legacy-provider";
	private static final String QUERY = "SELECT ?s WHERE { SERVICE <urn:legacy-provider> { "
			+ "GRAPH <urn:data> { ?s <urn:p> <urn:o> } } }";
	private static final String UNSUPPORTED = "Legacy-only SERVICE provider cannot handle Graph";

	@ParameterizedTest
	@EnumSource(value = GraphAlgebraMode.class, names = { "AUTO", "GRAPH" })
	void graphModeReachesAnUnnegotiatedLegacyOnlyServiceProvider(GraphAlgebraMode requested) {
		LegacyOnlyService service = new LegacyOnlyService();
		SailRepository repository = repository(service);
		try (var connection = repository.getConnection()) {
			if (requested != GraphAlgebraMode.AUTO) {
				connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(requested));
			}
			assertTrue(connection.getSailConnection().supportsGraphAlgebra());
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null);
			assertEquals(requested, connection.getQueryParseOptions().graphAlgebraMode());
			assertEquals(GraphAlgebraMode.GRAPH, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			assertEquals(0, service.invocations);

			QueryEvaluationException failure = assertThrows(QueryEvaluationException.class, () -> {
				try (var result = query.evaluate()) {
					result.hasNext();
				}
			});
			Throwable rootCause = failure;
			while (rootCause.getCause() != null) {
				rootCause = rootCause.getCause();
			}
			assertEquals(QueryEvaluationException.class, rootCause.getClass());
			assertEquals(UNSUPPORTED, rootCause.getMessage());
			assertEquals(1, service.invocations);
			assertEquals(1, service.rejectedGraphs);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void explicitLegacyProtectsTheUnnegotiatedServiceProvider() {
		LegacyOnlyService service = new LegacyOnlyService();
		SailRepository repository = repository(service);
		try (var connection = repository.getConnection()) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var result = query.evaluate()) {
				assertTrue(result.hasNext());
				assertEquals("urn:legacy-result", result.next().getValue("s").stringValue());
				assertFalse(result.hasNext());
			}
			assertEquals(1, service.invocations);
			assertEquals(0, service.rejectedGraphs);
			assertTrue(service.sawLegacyNamedContext);
		} finally {
			repository.shutDown();
		}
	}

	private static SailRepository repository(LegacyOnlyService service) {
		MemoryStore store = new MemoryStore();
		store.setFederatedServiceResolver(endpoint -> {
			assertEquals(ENDPOINT, endpoint);
			return service;
		});
		return new SailRepository(store);
	}

	private static final class LegacyOnlyService implements FederatedService {
		private int invocations;
		private int rejectedGraphs;
		private boolean sawLegacyNamedContext;

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projections,
				BindingSet bindings, String baseURI) {
			invocations++;
			service.getServiceExpr().visit(new AbstractQueryModelVisitor<QueryEvaluationException>() {
				@Override
				public void meet(Graph graph) {
					rejectedGraphs++;
					throw new QueryEvaluationException(UNSUPPORTED);
				}

				@Override
				public void meet(StatementPattern pattern) {
					sawLegacyNamedContext = pattern.getScope() == StatementPattern.Scope.NAMED_CONTEXTS
							&& pattern.getContextVar() != null && pattern.getContextVar().hasValue()
							&& "urn:data".equals(pattern.getContextVar().getValue().stringValue());
				}
			});
			if (!sawLegacyNamedContext) {
				throw new QueryEvaluationException("Expected a legacy named-context statement pattern");
			}
			MapBindingSet result = new MapBindingSet();
			result.addBinding("s", SimpleValueFactory.getInstance().createIRI("urn:legacy-result"));
			return new SingletonIteration<>(result);
		}

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseURI) {
			throw new AssertionError("This query must use SELECT");
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> bindings,
				String baseURI) {
			throw new AssertionError("This query must use scalar SELECT");
		}

		@Override
		public boolean isInitialized() {
			return true;
		}

		@Override
		public void initialize() {
		}

		@Override
		public void shutdown() {
		}
	}
}
